<?php $h=static fn($value)=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$csrf=alphano_csrf_token();$hasOwnVote=(bool)array_filter($rows,fn($r)=>(int)$r['idpg']===$pgId); ?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><title>Motivazioni dei voti – <?=$h(TitoloSito)?></title></head><body>
<section class="academy-workspace" aria-label="Motivazioni dei voti"><header class="forum-toolbar"><h2><?=$h($titolo)?></h2><a href="/admin/accademia.php" class="action-btn" data-icon="book">Torna all’Accademia</a></header><div class="ui-table-scroll" tabindex="0" role="region" aria-label="Voti e motivazioni"><table class="ui-data-table academy-table"><thead><tr><th scope="col">Votante</th><th scope="col">Voto</th><th scope="col">Motivazione</th><?php if($hasOwnVote): ?><th scope="col">Modifica il tuo voto</th><?php endif; ?></tr></thead><tbody>
<?php foreach($rows as $vote): ?><tr><td><a href="/profili/?Id=<?=(int)$vote['idpg']?>"><?=$h($vote['nome'])?></a></td><td><?=$vote['voto']==='vpos'?'Positivo':'Negativo'?></td><td><?=$h($vote['motivo'])?></td><?php if($hasOwnVote): ?><td><?php if((int)$vote['idpg']===$pgId): ?><form method="post" class="academy-vote-form"><input type="hidden" name="csrf_token" value="<?=$h($csrf)?>"><input type="hidden" name="azione" value="modifyvoto"><?php foreach(['org'=>$org,'corp'=>$corp,'obj'=>$obj,'giocata'=>$giocata] as $field=>$value):if($value): ?><input type="hidden" name="<?=$field?>" value="<?=(int)$value?>"><?php endif;endforeach; ?><label>Voto<select name="voto" required><option value="1" <?=$vote['voto']==='vpos'?'selected':''?>>Positivo</option><option value="0" <?=$vote['voto']==='vpos'?'':'selected'?>>Negativo</option></select></label><label>Motivazione<input type="text" name="motivo" value="<?=$h($vote['motivo'])?>" required maxlength="2000"></label><button type="submit" data-icon="check">Salva</button></form><?php else: ?>—<?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="<?=$hasOwnVote?4:3?>" class="ui-empty">Nessuna motivazione disponibile.</td></tr><?php endif; ?></tbody></table></div></section></body></html>
